def list_files(folder=None, owner=None):
    import json
    with open(__import__("os").path.join(_DB, 'files.json')) as f:
        fs = json.load(f)
    if folder:
        fs = [x for x in fs if x.get('folder') == folder]
    if owner:
        fs = [x for x in fs if x.get('owner') == owner]
    return fs

