def get_file(file_id):
    import json
    with open(__import__("os").path.join(_DB, 'files.json')) as f:
        fs = json.load(f)
    for x in fs:
        if x.get('file_id') == file_id:
            return x
    return {'found': False, 'file_id': file_id}

def search_files(query, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0562000" if __import__("os").path.isdir("./environment_mix/0562000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    ts = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Load/create usage log collection (not declared in schema, but required for observable service dynamics)
    usage_name = "usage.json"
    usage = _load(usage_name)
    if not isinstance(usage, dict):
        usage = {}
    if "requests" not in usage or not isinstance(usage.get("requests"), list):
        usage["requests"] = []
    if "counters" not in usage or not isinstance(usage.get("counters"), dict):
        usage["counters"] = {}
    usage["counters"].setdefault("total_requests", 0)
    usage["counters"].setdefault("search_files_requests", 0)

    def _log(status, error_code=None, **extra):
        latency_ms = int((time.time() - t0) * 1000)
        usage["counters"]["total_requests"] += 1
        usage["counters"]["search_files_requests"] += 1
        rec = {
            "timestamp": ts,
            "endpoint": "search_files",
            "status": status,
            "latency_ms": latency_ms,
        }
        if error_code:
            rec["error_code"] = error_code
        rec.update(extra)
        usage["requests"].append(rec)
        _save(usage_name, usage)

    # Rate limit enforcement (simple sliding window over usage log)
    # Limit: 120 requests / 60 seconds (service-global in this local store)
    try:
        now = datetime.datetime.utcnow()
        window_s = 60
        limit = 120
        recent = 0
        for r in reversed(usage["requests"]):
            rts = r.get("timestamp")
            if not isinstance(rts, str):
                continue
            try:
                rt = datetime.datetime.fromisoformat(rts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if (now - rt).total_seconds() <= window_s:
                recent += 1
                if recent >= limit:
                    _log("error", "RATE_LIMIT", reason="Too many requests", window_seconds=window_s, limit=limit)
                    return _err("RATE_LIMIT", "Too many requests, please slow down.", window_seconds=window_s, limit=limit)
            else:
                break
    except Exception:
        # If rate limit parsing fails due to malformed historical rows, don't block valid requests.
        pass

    # Validate input
    if query is None or not isinstance(query, str):
        _log("error", "VALIDATION_ERROR", reason="query must be a non-empty string")
        return _err("VALIDATION_ERROR", "Missing or invalid 'query'. It must be a non-empty string.")
    if query.strip() == "":
        _log("error", "VALIDATION_ERROR", reason="query cannot be only whitespace")
        return _err("VALIDATION_ERROR", "Invalid 'query'. It cannot be empty or only whitespace.")

    q = query.strip().lower()

    # Load files collection
    files_doc = _load("files.json")
    if isinstance(files_doc, dict) and isinstance(files_doc.get("rows"), list):
        files_rows = files_doc["rows"]
    elif isinstance(files_doc, list):
        files_rows = files_doc
    else:
        files_rows = []

    # Search
    matches = []
    for row in files_rows:
        if not isinstance(row, dict):
            continue
        name = row.get("name", "")
        if isinstance(name, str) and q in name.lower():
            matches.append(row)

    resp = {
        "data": matches,
        "meta": {
            "query": query,
            "total": len(matches),
            "has_more": False,
            "next_cursor": None,
        },
    }
    _log("ok", returned=len(matches))
    return resp
